SELECT *
FROM dc_customer_risk_refund
WHERE del_flag = 0

    AND lawyer_id = #{userId}


    AND YEAR(create_time) = #{year}


    AND MONTH(create_time) = #{month}


    AND DAY(create_time) = #{day}


    AND customer_type = #{customerType}

SELECT count(1) as count ,sum(refund_amount) as sum
FROM dc_customer_risk_refund
WHERE del_flag = 0

    AND lawyer_id = #{userId}


    AND YEAR(create_time) = #{year}


    AND MONTH(create_time) = #{month}


    AND DAY(create_time) = #{day}


    AND customer_type = #{customerType}
